async function resourceAction(resourceId, action) { const path = `${projectPath("/resources/")}${endpoint(resourceId)}${action === "attach" ? "/attach" : action === "detach" ? "/attach" : ""}`; if (action === "delete" && !window.confirm(t("removeResourceConfirm"))) return; try { const response = await api(path, {method:action === "attach" ? "POST" : "DELETE"}); saveProjectResponse(await response.json()); $("#pdf-file").value = ""; $("#file-name").textContent = t("maxSize"); } catch (error) { notify(error.message, true); } }
