async function approveAgenda() { try { const response = await api(projectPath("/agenda/approve"), {method:"POST"}); saveProjectResponse(await response.json()); notify(t("agendaApproved")); } catch (error) { notify(error.message, true); } }
async function selectTemplate(payload) { if (!currentPresentation()) return notify(t("createPresentationFirst"), true); try { const response = await api(projectPath("/theme"), {method:"PUT", headers:{"Content-Type":"application/json"}, body:JSON.stringify(payload)}); saveProjectResponse(await response.json()); } catch (error) { notify(error.message, true); } }
async function savePresentationDetails() { const fields = {presenterName:"presenter_name", presenterTitle:"presenter_title", organization:"organization", eventName:"event_name", venue:"venue", presentationDate:"presentation_date"}; const body = Object.fromEntries(Object.entries(fields).map(([label, name]) => [name, document.querySelector(`[data-presentation-detail="${label}"]`)?.value || ""])); try { const response = await api(projectPath("/presentation/details"), {method:"PUT", headers:{"Content-Type":"application/json"}, body:JSON.stringify(body)}); saveProjectResponse(await response.json()); notify(t("changeSaved")); } catch (error) { notify(error.message, true); } }
async function saveEvidenceSettings() { const body = {evidence_context_mode: $("#evidence-context-mode")?.value || "bm25", patient_case_mode: Boolean($("#patient-case-mode")?.checked), patient_case_acknowledged: Boolean($("#patient-case-acknowledged")?.checked)}; try { const response = await api(projectPath("/evidence-settings"), {method:"PUT", headers:{"Content-Type":"application/json"}, body:JSON.stringify(body)}); saveProjectResponse(await response.json()); notify(t("changeSaved")); } catch (error) { notify(error.message, true); } }
function previewTemplate(theme) { const modal = $("#template-modal"), preview = $("#template-modal-preview"); $("#template-modal-title").textContent = t(`theme_${theme}`); preview.className = `template-large-preview ${theme}`; modal.hidden = false; }
async function uploadCustomTemplate() { const file = $("#template-file")?.files[0]; if (!file) return; if (!file.name.toLowerCase().endsWith(".pptx")) return notify(t("pptxOnly"), true); const form = new FormData(); form.append("file", file); try { await api(`/users/${endpoint(state.userId)}/templates`, {method:"POST", body:form}); await loadTemplates(); render(); notify(t("templateAdded")); } catch (error) { notify(error.message, true); } }

$("#project-id").addEventListener("change", async event => { state.projectId = event.target.value; localStorage.setItem(`hpa_project_${state.userId}`, state.projectId); try { await openProject(); } catch (error) { notify(error.message, true); } });
$("#create-project").addEventListener("click", createProject); $("#logout").addEventListener("click", logout); $("#delete-project").addEventListener("click", deleteProject); $("#delete-user").addEventListener("click", deleteUser); $("#login").addEventListener("click", () => authenticate("/auth/login")); $("#register").addEventListener("click", () => authenticate("/auth/register")); $("#reset-password").addEventListener("click", () => authenticate("/auth/reset-password"));
$("#auth-language").addEventListener("change", event => { state.profile.preferred_language = event.target.value; applyLanguage(); }); $("#user-language").addEventListener("change", updateProfile); $("#user-role").addEventListener("change", updateProfile);
$("#pdf-file").addEventListener("change", event => { const file = event.target.files[0]; $("#file-name").textContent = file ? file.name : t("maxSize"); $("#upload-resource").disabled = !file; }); $("#upload-resource").addEventListener("click", uploadResource); $("#validate-resources").addEventListener("click", () => simpleAction("/resources/validate")); $("#analyze-resources").addEventListener("click", analyzeResources); $("#chat-form").addEventListener("submit", sendChat); $("#export-pptx").addEventListener("click", exportPptx);
$("#resource-list").addEventListener("click", event => { const button = event.target.closest("button[data-resource-id]"); if (button) resourceAction(button.dataset.resourceId, button.dataset.resourceAction); });
$("#resource-analysis-area").addEventListener("click", event => { if (event.target.dataset.action === "resource-discuss") discussResources(); });
$("#presentation-setup-area").addEventListener("click", event => { if (event.target.dataset.action === "setup-presentation") setupPresentation(); });
$("#resource-workflow-action").addEventListener("click", event => { if (event.target.dataset.action === "validate-resources") simpleAction("/resources/validate"); if (event.target.dataset.action === "setup-presentation") setupPresentation(); });
document.querySelectorAll(".workspace-tab").forEach(button => button.addEventListener("click", () => setWorkspace(button.dataset.workspace)));
$("#presentation-settings").addEventListener("click", event => { const button = event.target.closest("button"); if (!button) return; if (button.dataset.previewTheme) previewTemplate(button.dataset.previewTheme); if (button.dataset.theme) selectTemplate({theme:button.dataset.theme}); if (button.dataset.customTemplate) selectTemplate({custom_template_id:button.dataset.customTemplate}); if (button.id === "upload-template") uploadCustomTemplate(); });
$("#project-evidence-settings").addEventListener("change", event => { if (event.target.id === "evidence-context-mode") { const description = $("#evidence-mode-description"); if (description) description.textContent = event.target.value === "direct_bounded" ? t("directModeDescription") : t("bm25ModeDescription"); } if (event.target.id === "patient-case-mode") { const acknowledgement = $("#patient-case-acknowledged"); acknowledgement.disabled = !event.target.checked; if (!event.target.checked) acknowledgement.checked = false; } }); $("#project-evidence-settings").addEventListener("click", event => { if (event.target.dataset.action === "save-evidence-settings") saveEvidenceSettings(); });
$("#close-template-modal").addEventListener("click", () => { $("#template-modal").hidden = true; }); $("#template-modal").addEventListener("click", event => { if (event.target.id === "template-modal") event.currentTarget.hidden = true; });
$("#agenda-area").addEventListener("click", event => { const action = event.target.dataset.action; if (action === "agenda-save") saveAgenda(); if (action === "agenda-approve") approveAgenda(); }); $("#next-action").addEventListener("click", event => { if (event.target.dataset.action === "validate-resources") simpleAction("/resources/validate"); });
$("#presentation-details-area").addEventListener("click", event => { if (event.target.dataset.action === "presentation-details-save") savePresentationDetails(); });
$("#final-actions").addEventListener("click", event => { const action = event.target.dataset.action; if (action === "blueprint-generate") startGeneration("blueprint"); if (action === "slides-generate") startGeneration("slides"); if (action === "blueprint-approve") simpleAction("/blueprint/approve"); if (action === "slides-approve") simpleAction("/slides/approve"); if (action === "final-approve") simpleAction("/presentation/approve"); }); $("#review-area").addEventListener("click", event => { const button = event.target.closest("button"); if (!button) return; if (button.dataset.review) reviewAction(button); if (button.dataset.edit) saveUserEdit(button); if (button.dataset.action === "blueprint-regenerate") simpleAction("/blueprint/regenerate"); });
applyLanguage();
(async () => { if (state.userId && state.token) { try { await startWorkspace(); } catch (error) { logout(); } } })();
